Ext._define('standard.ChoiceGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'standard.ChoiceWindow',

    showBoolean: function(value){
        return value ? 'SIM' : 'NÃO'
    },

    getFilterMenu: function() {
        return [
            {
                'text': 'Apenas ativos',
                'checked': true,
                'hideOnClick': false,
                'scope': this,
                'handler': this.filterActive
            }
        ];
    },

    filterActive: function() {
        this._filterActive = core.nullValue(this._filterActive, true);

        if(this._filterActive == false) {
            this._filterActive = true;
            this.setFilterProperty('active', this._filterActive, 1011);
        }else {
            this.removeFilterProperty('active', 1011);
            this._filterActive = false;
        }
    },

    alignColumn: function(value) {
        return '<div style="text-align:center">' + value + '</div>';
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Aplicativo', dataIndex: 'app_label', width: 200},
                    {header: 'Nome da constante', dataIndex: 'name', width: 200},
                    {
                        header: 'Valor (int)',
                        menuDisabled: true,
                        dataIndex: 'value',
                        width: 40,
                        renderer: this.alignColumn
                    },
                    {
                        header: 'Valor (char)',
                        menuDisabled: true,
                        dataIndex: 'cvalue',
                        width: 40,
                        renderer: this.alignColumn
                    },
                    {header: 'Label', dataIndex: 'label', id: 'autoExpandColumn'},
                    {header: 'Peso ordenação', dataIndex: 'order_weight', width: 110},
                    {header: 'Ativo', dataIndex: 'active', width: 50, renderer: this.showBoolean},
                    {header: 'Descrição', dataIndex: 'description', width: 400},
                ]
            );

        return this._columnModel;
    }
});

core.RestfulGrid.register(
    'standard.ChoiceRestful',
    'standard.ChoiceGrid'
);

